    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:
        row, col = 0, 0
        visited = {(0, 0)}
        max_row, max_col = len(grid), len(grid[0])

        while 0 <= row < max_row and 0 <= col < max_col and (row, col) not in visited:
