class Solution:
    def maxEqualPairs(self, nums: list[int]) -> int:
        counter = {}
        for num in nums:
            counter[num] = counter.get(num, 0) + 1

        sorted_keys = sorted(counter.keys())
        total_pairs = 0
        remaining_pairs = sum(counter.values())
        for key in sorted_keys:
            value = counter[key]
            pairs_found = value * (remaining_pairs - value)
            remaining_pairs -= value
            total_pairs = max(total_pairs, pairs_found)

        return total_pairs

